"""Constructor-based circle packing for n=26 circles"""
import numpy as np


def _compute_radii(centers):
    """Maximal feasible radii for fixed centers (border + pairwise non-overlap)."""
    n = centers.shape[0]
    border = np.minimum.reduce([
        centers[:, 0], centers[:, 1],
        1.0 - centers[:, 0], 1.0 - centers[:, 1],
    ])
    radii = border.copy()
    for _ in range(300):
        new = radii.copy()
        for i in range(n):
            for j in range(n):
                if i == j:
                    continue
                d = np.hypot(centers[i, 0] - centers[j, 0], centers[i, 1] - centers[j, 1])
                cap = d - radii[j]
                if cap < new[i]:
                    new[i] = cap
        new = np.clip(new, 0.0, border)
        if np.max(np.abs(new - radii)) < 1e-11:
            radii = new
            break
        radii = new
    return radii


def _score(centers):
    return float(np.sum(_compute_radii(centers)))


def construct_packing():
    """Deterministic explicit layout of 26 circles, then a bounded refinement.

    Layout: a 5x5 grid of 25 circles plus a 26th tucked into a central gap,
    all placed explicitly. A short, deterministic coordinate refinement then
    nudges positions to increase the sum of the maximal feasible radii.
    """
    n = 26
    grid = np.array([0.1, 0.3, 0.5, 0.7, 0.9])
    xs, ys = np.meshgrid(grid, grid)
    centers = np.column_stack([xs.ravel(), ys.ravel()])[:n].copy()

    # Bounded deterministic refinement: try small axis-aligned nudges per circle,
    # keep a move only if it increases the total sum of radii.
    best = centers.copy()
    best_score = _score(best)
    steps = [0.04, 0.02, 0.01, 0.005]
    for step in steps:
        improved = True
        while improved:
            improved = False
            for i in range(n):
                for dx in (-step, step):
                    for dy in (-step, step):
                        trial = best.copy()
                        trial[i, 0] = np.clip(best[i, 0] + dx, 0.02, 0.98)
                        trial[i, 1] = np.clip(best[i, 1] + dy, 0.02, 0.98)
                        s = _score(trial)
                        if s > best_score + 1e-10:
                            best = trial
                            best_score = s
                            improved = True
    radii = _compute_radii(best)
    return best, radii, float(np.sum(radii))


def compute_max_radii(centers):
    return _compute_radii(centers)

